window.HameleonMotivo = [["SS-001","B3ADA1"],["SS-002","817C72"],["SS-003","645E57"],["SS-004","4C4B48"],["SS-005","747878"],["SS-006","70757C"],["SS-007","686E74"],["SS-008","737971"],["SS-009","6A7B78"],["SS-010","506668"],["SS-011","456A79"],["SS-012","1C5A7A"],["SS-013","254F75"],["SS-014","677264"],["SS-015","586C61"],["SS-016","4E6565"],["SS-017","52726F"],["SS-018","486F6F"],["SS-019","3C696F"],["SS-020","235B69"],["SS-021","5A7B6D"],["SS-022","3A7264"],["SS-023","818273"],["SS-024","747C66"],["SS-025","5E6B49"],["SS-026","868263"],["SS-027","8C8650"],["SS-028","817748"],["SS-029","918D4C"],["SS-030","807939"],["SS-031","6D6B40"],["SS-032","82785F"],["SS-033","847A5E"],["SS-034","908563"],["SS-035","94784D"],["SS-036","967C2E"],["SS-037","8F7A52"],["SS-038","84704D"],["SS-039","7C6C49"],["SS-040","79663F"],["SS-041","886F5B"],["SS-042","8E664B"],["SS-043","985F37"],["SS-044","7E7571"],["SS-045","726462"],["SS-046","6C5453"],["SS-047","8B7163"],["SS-048","885F50"],["SS-049","825448"],["SS-050","92464B"],["SS-051","896E6A"],["SS-052","806B67"],["SS-053","815E65"],["SS-054","865857"],["SS-055","79435A"],["SS-056","7A7271"],["SS-057","6E6270"],["SS-058","58466D"],["SS-059","80767E"],["SS-060","9B8A7C"],["SS-061","95766E"],["SS-062","706353"],["SS-063","887B5A"],["SS-064","827B65"],["SS-065","908B7D"],["SS-066","878164"],["SS-067","7E7665"],["SS-068","7C756B"],["SS-069","817C74"],["SS-070","847F77"],["SS-071","918A7A"],["SS-072","8B8478"],["SS-073","91897D"],["SS-074","807671"],["SS-075","7F786F"],["SS-076","907F6F"],["SS-077","807973"],["SS-078","7F7974"],["SS-079","858071"],["SS-080","888179"],["GG-001","AB7F1C"],["GG-002","896828"],["GG-003","68491F"],["GG-004","6E5B26"],["GG-005","87521C"],["GG-006","94470E"],["GG-007","8E2D14"],["GG-008","994019"],["GG-009","9A5014"],["GG-010","985326"],["GG-011","723D12"],["GG-012","79441E"],["GG-013","56360B"],["GG-014","494021"],["GG-015","886E30"],["GG-016","645521"],["GG-017","505119"],["GG-018","6B7438"],["GG-019","5A611A"],["GG-020","496319"],["GG-021","2A571A"],["TT-001","8C867A"],["TT-002","63635F"],["TT-003","434440"],["TT-004","63696B"],["TT-005","235361"],["TT-006","1B4F6A"],["TT-007","223B46"],["TT-008","706439"],["TT-009","71623D"],["TT-010","737150"],["TT-011","70703A"],["TT-012","5B644C"],["TT-013","325F54"],["TT-014","754835"],["TT-015","743436"],["TT-016","66354D"],["TT-017","7A5A4F"],["TT-018","78655A"],["TT-019","615048"],["TT-020","413154"],["TT-021","3D3946"],["TT-022","6C695E"],["TT-023","6D6A5E"]];
window.HameleonMotivoBases = [{"key":"silver","name":"Silver","prefix":"SS"},{"key":"gold","name":"Gold","prefix":"GG"},{"key":"titanium","name":"Titanium","prefix":"TT"}];

/* Shared Motivo helpers: which base a product is, and a typed code ("S12", "ss-012", or "12" with a known base) to a colour. */
window.Hameleon = window.Hameleon || {};
window.Hameleon.motivo = {
  baseOf(text) {
    const t = String(text || '').toLowerCase();
    if (/silver|сребър|сребр/.test(t)) return 'silver';
    if (/gold|злат/.test(t)) return 'gold';
    if (/titan|титан/.test(t)) return 'titanium';
    return '';
  },
  base(key) {
    return window.HameleonMotivoBases.find((b) => b.key === key || b.prefix === key) || null;
  },
  normalize(input, baseKey) {
    const m = String(input || '').trim().match(/^(ss|gg|tt|s|g|t)?\s*-?\s*(\d{1,3})$/i);
    if (!m) return '';
    const letter = m[1] ? m[1][0].toUpperCase() : '';
    const base = letter ? this.base(letter + letter) : this.base(baseKey);
    return base ? `${base.prefix}-${m[2].padStart(3, '0')}` : '';
  },
  /* imageUrl: the asset URL of hm-mz-ss-001.jpg; other photos share its folder and version. */
  find(input, baseKey, imageUrl) {
    const code = this.normalize(input, baseKey);
    const item = code && window.HameleonMotivo.find((m) => m[0] === code);
    if (!item) return null;
    const base = this.base(code.slice(0, 2));
    return {
      code,
      name: `Motivo ${base.name}`,
      hex: `#${item[1]}`,
      catalogue: 'Motivo',
      base: base.key,
      image: imageUrl ? String(imageUrl).replace('hm-mz-ss-001', `hm-mz-${code.toLowerCase()}`) : '',
    };
  },
};

/*
  Shared Vitex helpers. The two collections share some codes (e.g. 1110 is in both), so a lookup
  tries the preferred collection first. Global codes are 4 digits: "893" means 0893.
*/
window.Hameleon.vitex = {
  collections: [
    { key: 'global', name: 'Global Collection', families: () => window.HameleonColors.families },
    { key: 'colourful', name: 'Colourful Collection', families: () => window.HameleonColourful.families },
  ],
  collection(key) {
    return this.collections.find((c) => c.key === key || c.name === key || `Vitex ${c.name}` === key) || null;
  },
  /* "cl11", "Cl 11" and "CL 11" are the same code. */
  key(code) {
    return String(code || '').replace(/^№\s*/, '').replace(/\s+/g, '').toUpperCase();
  },
  color(collection, item, family) {
    const named = item.length > 2;
    return {
      code: String(item[0]),
      name: named ? item[1] : '',
      hex: `#${named ? item[2] : item[1]}`,
      catalogue: 'Vitex',
      collection: collection.name,
      family: family.name,
    };
  },
  findIn(key, input) {
    const collection = this.collection(key);
    if (!collection) return null;
    let wanted = this.key(input);
    if (!wanted) return null;
    if (collection.key === 'global' && /^\d{1,4}$/.test(wanted)) wanted = wanted.padStart(4, '0');
    const q = String(input).trim().toLowerCase();
    for (const family of collection.families()) {
      const item = family.items.find((c) => this.key(c[0]) === wanted || (c.length > 2 && c[1].toLowerCase() === q));
      if (item) return this.color(collection, item, family);
    }
    return null;
  },
  /* prefer: 'global' or 'colourful'; the other collection is tried next. */
  find(input, prefer) {
    const order = prefer === 'colourful' ? ['colourful', 'global'] : ['global', 'colourful'];
    for (const key of order) {
      const color = this.findIn(key, input);
      if (color) return color;
    }
    return null;
  },
};
